package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSheetToday {
    public void validate(@RequestBody SheetToday request, Out<LocalDate> today) throws InvalidTodayException {
        String value = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(value));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException(value);
        }
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the rate once it has passed every rule and is stored. */
public class AuditRateSet {
    public void audit(@Val Rate rate, @RequestParam(value = "user", required = false) String user, Audit audit) {
        audit.record("RATE_SET sheet=" + rate.sheetId() + " by=" + user
                + " grade=" + rate.grade() + " rate=" + rate.pct().toPlainString()
                + (rate.from() == null ? "" : " from=" + rate.from()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") long claimId,
            ClaimRepository repository, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = repository.findById(sheetId, claimId);
        if (claim == null) throw new ClaimNotFoundException(claimId);
        claimOut.set(claim);
    }
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A refused request: `reason` is the server's explanation (the response text), for the screen.
export class HttpError extends Error {
  constructor(message: string, readonly status: number, readonly reason: string) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    const reason = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, reason);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

